Literal.Value:
'{
  "$schema": "https://vega.github.io/schema/vega-lite/v5.json",
  "data": {
    "name": "dataset"
  },
  "config": {
    "background": "transparent",
    "view": {
      "stroke": null
    },
    "font": "Segoe UI",
    "axis": {
      "labelColor": "#9AA6B0",
      "labelFont": "Segoe UI",
      "labelFontSize": 10,
      "titleColor": "#9AA6B0",
      "titleFont": "Segoe UI",
      "titleFontWeight": "normal",
      "titleFontSize": 10,
      "domain": false,
      "ticks": false,
      "gridColor": "#2C363E"
    },
    "legend": {
      "labelColor": "#9AA6B0",
      "titleColor": "#9AA6B0",
      "labelFont": "Segoe UI"
    },
    "title": {
      "color": "#C9D3DB",
      "font": "Segoe UI Semibold",
      "fontSize": 12,
      "fontWeight": "normal",
      "anchor": "start",
      "offset": 12
    },
    "locale": {
      "number": {
        "decimal": ",",
        "thousands": ".",
        "grouping": [
          3
        ],
        "currency": [
          "R$ ",
          ""
        ]
      },
      "time": {
        "dateTime": "%A, %e de %B de %Y. %X",
        "date": "%d/%m/%Y",
        "time": "%H:%M:%S",
        "periods": [
          "AM",
          "PM"
        ],
        "days": [
          "Domingo",
          "Segunda",
          "Terça",
          "Quarta",
          "Quinta",
          "Sexta",
          "Sábado"
        ],
        "shortDays": [
          "Dom",
          "Seg",
          "Ter",
          "Qua",
          "Qui",
          "Sex",
          "Sáb"
        ],
        "months": [
          "Janeiro",
          "Fevereiro",
          "Março",
          "Abril",
          "Maio",
          "Junho",
          "Julho",
          "Agosto",
          "Setembro",
          "Outubro",
          "Novembro",
          "Dezembro"
        ],
        "shortMonths": [
          "Jan",
          "Fev",
          "Mar",
          "Abr",
          "Mai",
          "Jun",
          "Jul",
          "Ago",
          "Set",
          "Out",
          "Nov",
          "Dez"
        ]
      }
    }
  },
  "title": {
    "text": "Clientes por porte e tendência · cada ponto é um cliente"
  },
  "width": "container",
  "height": "container",
  "transform": [
    {
      "filter": "datum[''Qtd''] > 0"
    },
    {
      "calculate": "isValid(datum[''QtdAA'']) && datum[''QtdAA''] > 0 ? datum[''Qtd''] / datum[''QtdAA''] - 1 : 0",
      "as": "var"
    },
    {
      "calculate": "max(min(datum.var, 1), -0.6)",
      "as": "vplot"
    },
    {
      "calculate": "datum[''Qtd''] >= datum[''Media'']",
      "as": "grande"
    },
    {
      "calculate": "datum[''Qtd''] >= (isValid(datum[''QtdAA'']) ? datum[''QtdAA''] : 0)",
      "as": "cresce"
    },
    {
      "calculate": "datum.grande ? (datum.cresce ? ''Fortalezas'' : ''Atenção'') : (datum.cresce ? ''Oportunidades'' : ''Fraquezas'')",
      "as": "quad"
    }
  ],
  "layer": [
    {
      "mark": {
        "type": "point",
        "filled": true,
        "size": 54,
        "opacity": 0.85,
        "stroke": "#1A2026",
        "strokeWidth": 0.6
      },
      "encoding": {
        "x": {
          "field": "Qtd",
          "type": "quantitative",
          "scale": {
            "zero": false,
            "nice": true
          },
          "axis": {
            "title": "Baterias no período →",
            "format": ",.0f",
            "grid": true,
            "gridDash": [
              2,
              3
            ],
            "tickCount": 5
          }
        },
        "y": {
          "field": "vplot",
          "type": "quantitative",
          "scale": {
            "domain": [
              -0.6,
              1
            ]
          },
          "axis": {
            "title": "vs mesmo período AA →",
            "format": "+.0%",
            "grid": true,
            "gridDash": [
              2,
              3
            ],
            "values": [
              -0.5,
              -0.25,
              0,
              0.25,
              0.5,
              0.75,
              1
            ]
          }
        },
        "color": {
          "field": "quad",
          "type": "nominal",
          "scale": {
            "domain": [
              "Fortalezas",
              "Atenção",
              "Oportunidades",
              "Fraquezas"
            ],
            "range": [
              "#3FB68B",
              "#F2B84B",
              "#5B8DB8",
              "#E5484D"
            ]
          },
          "legend": null
        },
        "tooltip": [
          {
            "field": "Cliente"
          },
          {
            "field": "Ramo"
          },
          {
            "field": "Municipio",
            "title": "Município"
          },
          {
            "field": "quad",
            "title": "Quadrante"
          },
          {
            "field": "Qtd",
            "format": ",.0f",
            "title": "Baterias"
          },
          {
            "field": "QtdAA",
            "format": ",.0f",
            "title": "Ano anterior"
          },
          {
            "field": "var",
            "format": "+.1%",
            "title": "Variação"
          }
        ]
      }
    },
    {
      "mark": {
        "type": "rule",
        "color": "#9AA6B0",
        "strokeDash": [
          4,
          4
        ],
        "opacity": 0.7
      },
      "encoding": {
        "x": {
          "aggregate": "max",
          "field": "Media",
          "type": "quantitative"
        }
      }
    },
    {
      "mark": {
        "type": "rule",
        "color": "#9AA6B0",
        "strokeDash": [
          4,
          4
        ],
        "opacity": 0.7
      },
      "encoding": {
        "y": {
          "datum": 0
        }
      }
    },
    {
      "data": {
        "values": [
          {}
        ]
      },
      "mark": {
        "type": "text",
        "text": "FORTALEZAS",
        "x": {
          "expr": "width - 6"
        },
        "y": 4,
        "align": "right",
        "baseline": "top",
        "fontSize": 10,
        "fontWeight": 600,
        "color": "#3FB68B",
        "opacity": 0.9
      }
    },
    {
      "data": {
        "values": [
          {}
        ]
      },
      "mark": {
        "type": "text",
        "text": "ATENÇÃO",
        "x": {
          "expr": "width - 6"
        },
        "y": {
          "expr": "height - 6"
        },
        "align": "right",
        "baseline": "bottom",
        "fontSize": 10,
        "fontWeight": 600,
        "color": "#F2B84B",
        "opacity": 0.9
      }
    },
    {
      "data": {
        "values": [
          {}
        ]
      },
      "mark": {
        "type": "text",
        "text": "OPORTUNIDADES",
        "x": 6,
        "y": 4,
        "align": "left",
        "baseline": "top",
        "fontSize": 10,
        "fontWeight": 600,
        "color": "#5B8DB8",
        "opacity": 0.9
      }
    },
    {
      "data": {
        "values": [
          {}
        ]
      },
      "mark": {
        "type": "text",
        "text": "FRAQUEZAS",
        "x": 6,
        "y": {
          "expr": "height - 6"
        },
        "align": "left",
        "baseline": "bottom",
        "fontSize": 10,
        "fontWeight": 600,
        "color": "#E5484D",
        "opacity": 0.9
      }
    }
  ]
}'
